-- R2B audited relationship creation and updates.
CREATE OR REPLACE FUNCTION public.mmhr_record_relationship(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; item public.relationships%ROWTYPE; v_org uuid; v_actor uuid; v_id uuid; v_action text; v_revision integer; v_subject_org uuid; v_related_org uuid; v_subject_contact uuid; v_related_contact uuid;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','update') OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'relationshipId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR correlation_id IS NULL OR idempotency_key IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid relationship input'; END IF;
 v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; v_id:=(payload->>'relationshipId')::uuid; v_action:=payload->>'action'; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record relationship',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF; receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r2b.relationship',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('relationshipId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF payload->>'relationshipType' NOT IN ('customer_vendor','customer_contact','vendor_contact','partner','other') OR payload->>'influence' NOT IN ('unknown','low','medium','high') OR (payload->>'subjectOrganizationId' IS NULL AND payload->>'subjectContactId' IS NULL) OR (payload->>'relatedOrganizationId' IS NULL AND payload->>'relatedContactId' IS NULL) OR (payload->>'subjectOrganizationId' IS NOT NULL AND payload->>'subjectContactId' IS NOT NULL) OR (payload->>'relatedOrganizationId' IS NOT NULL AND payload->>'relatedContactId' IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid relationship endpoints'; END IF;
   v_subject_org:=NULLIF(payload->>'subjectOrganizationId','')::uuid; v_related_org:=NULLIF(payload->>'relatedOrganizationId','')::uuid; v_subject_contact:=NULLIF(payload->>'subjectContactId','')::uuid; v_related_contact:=NULLIF(payload->>'relatedContactId','')::uuid;
   IF (v_subject_org IS NOT NULL AND v_related_org IS NOT NULL AND v_subject_org=v_related_org) OR (v_subject_contact IS NOT NULL AND v_related_contact IS NOT NULL AND v_subject_contact=v_related_contact) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Relationship endpoints must differ'; END IF;
   IF v_subject_contact IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.organization_id=v_org AND c.id=v_subject_contact) OR v_related_contact IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.contacts c WHERE c.organization_id=v_org AND c.id=v_related_contact) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Relationship contact denied'; END IF;
   INSERT INTO public.relationships(id,organization_id,relationship_type,subject_organization_id,subject_contact_id,related_organization_id,related_contact_id,owner_identity_id,influence,preference,status,created_by_identity_id) VALUES(v_id,v_org,payload->>'relationshipType',v_subject_org,v_subject_contact,v_related_org,v_related_contact,NULLIF(payload->>'ownerIdentityId','')::uuid,payload->>'influence',NULLIF(payload->>'preference',''),'active',v_actor) RETURNING * INTO item;
 ELSE
   v_revision:=(payload->>'expectedRevision')::integer; IF v_revision IS NULL OR v_revision<=0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid relationship revision'; END IF; SELECT * INTO item FROM public.relationships WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND OR item.revision<>v_revision THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Relationship is stale'; END IF;
   IF payload->>'influence' IS NOT NULL AND payload->>'influence' NOT IN ('unknown','low','medium','high') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid relationship influence'; END IF;
   UPDATE public.relationships SET influence=coalesce(payload->>'influence',influence),preference=CASE WHEN payload ? 'preference' THEN NULLIF(payload->>'preference','') ELSE preference END,status=coalesce(payload->>'status',status),revision=revision+1,updated_by_identity_id=v_actor,updated_at=clock_timestamp() WHERE id=v_id AND organization_id=v_org RETURNING * INTO item;
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r2b.relationship','relationship.'||v_action,'relationship',item.id,v_org,'Record relationship',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('relationshipId',item.id,'organizationId',item.organization_id,'influence',item.influence,'status',item.status,'revision',item.revision,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_relationship(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_relationship(jsonb,uuid,uuid) TO authenticated;
